from review import *
def save(p,d):Path(p).write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
for lang in ('da','en'):
 name='moby-dick'+('.da' if lang=='da' else '')+'.json';g=load('source/'+name);g['title']='Moby-Dick'
 if lang=='da':
  g['length']='135 kapitler, epilog og fortekster'
  g['openingText']='Kald mig Ishmael. For nogle år siden – hvor mange kan være lige meget – havde jeg få eller ingen penge i pungen, og der var ikke noget på land, der interesserede mig synderligt. Så jeg fik lyst til at sejle lidt omkring og se den del af verden, der er dækket af vand.'
  g['about']='Når en rå november breder sig i Ishmaels sjæl, tager han til søs. Denne gang skal det være på hvalfangst. På en kro i New Bedford deler han modvilligt seng med harpuneren Queequeg. Snart er de venner og drager sammen til Nantucket, hvor de mønstrer på Pequod. Først ude på havet får mandskabet at vide, hvad kaptajn Ahab vil med rejsen. Det er ham ligegyldigt, hvor mange tønder tran de får med hjem, hvis han kan ramme den hvide hval, der tog hans ben.\n\nHerman Melville havde selv sejlet på hvalfangst. Da romanen udkom i 1851, tilegnede han den Nathaniel Hawthorne. I den amerikanske udgave har en hjælpelærer og en under-underbibliotekar ordet, før Ishmael får lov at præsentere sig. Den ene slår ordet »hval« op. Den anden har samlet alt, hvad han har kunnet finde skrevet om dyret, lige fra Jobs Bog til råb fra en mastetop.\n\nUde på havet kan fortællingen lige så pludseligt skifte form. En nat taler sømændene hen over hovedet på hinanden som på en scene. En anden nat står Ishmael ved roret i skæret fra trangryderne. Og når han forsøger at inddele alle verdens hvaler efter størrelse, låner han sit system fra en boghylde.'
  desc=['Ishmael har stået i et klasseværelse og sejlet på handelsskibe, før han tager hyre som menig på Pequod. Han kan tale som en prædikant og straks efter slå over i en vittighed på egen bekostning. Læg mærke til, hvornår hans »jeg« træder tilbage, så en anden kan få ordet.','Pequods kaptajn mistede sit ben i et tidligere møde med Moby Dick. Nu støtter han sig på et ben af kaskelottens kæbeben. Da han sømmer en dublon fra Ecuador fast til masten, kan hver mand på dækket drømme om at blive den første, der ser hvalen.','En vældig kaskelot, som søfolk kender på den hvide pukkel og den rynkede pande. For Ahab er dens udfald et personligt angreb. Ishmael kan bruge et helt kapitel på at undersøge, hvordan den samme hvide farve kan fremkalde både ærefrygt og rædsel.','Førstestyrmanden er kvæker fra Nantucket og en dygtig hvalfanger. Han tør sige Ahab imod på agterdækket. Senere står han med en ladt musket uden for den sovende kaptajns kahyt og må afgøre, hvor langt hans ansvar for mandskabet rækker.','Andenstyrmanden kommer fra Cape Cod. I hans mundvig sidder piben, og selv under en jagt kan han tale til roerne, som sad de omkring middagsbordet. Hans gode humør kan både holde folk i live og lukke munden på dem.','Harpuneren kommer fra Rokovoko, hvor hans far er konge. Hans venskab med Ishmael begynder under samme sengetæppe i New Bedford. På overfarten til Nantucket springer han efter en mand, der er faldet i vandet efter at have gjort nar af ham.']
  g['cast'][1]['name']='Kaptajn Ahab';g['cast'][5]['role']='Harpuneren'
  g['whyItMatters']=[dict(title='Hvad koster en dublon?',body='Ahab sømmer mønten fast til masten, hvor alle kan se den. Den er løn til den første, der får øje på hvalen, men ingen er enige om, hvad billederne på den betyder. I kapitel 99 behøver mønten ikke flytte sig en tomme for at vise os, hvor langt der er fra den ene sømand til den næste.'),dict(title='En bog med mange stemmer',body='Prøv at læse prædikenen i kapitel 9 højt, og lyt så til mændene på bakken ved midnat i kapitel 40. Begge steder kan ordene sætte en hel forsamling i bevægelse. Men i kapellet har én mand ordet, mens det på dækket kan være svært at få lov at synge en vise til ende.'),dict(title='Et arbejde til søs',body='Når en hval er dræbt, er arbejdet knap begyndt. Spækket skal flænses af, hejses op, hakkes i stykker og koges. Læg mærke til, hvor folk sætter fødderne og holder hænderne. Selv en løs bugt på et tov kan afgøre, hvem der kommer hjem.')]
  gs=[('Ahabs besættelse','På agterdækket gør Ahab sin private hævn til et fælles foretagende. Hvem lader sig overtale, og hvem tier bare stille?','Jeg vil følge besætningens reaktioner, når Ahab kræver dens troskab.'),('Hvad ser de i hvalen?','For Starbuck er Moby Dick et dyr, der forsvarer sig. Ahab ser en vilje bag det hvide hoved. Ishmael kan rumme begge tanker længe nok til at blive bange for dem begge.','Jeg vil følge, hvordan synet på den samme hval skifter fra person til person.'),('Ishmaels blik','Ishmael kan begynde med en detalje på et stykke værktøj og ende i Jobs Bog. Hvornår følger jeg ham, og hvornår får han mig til at tvivle?','Jeg vil lægge mærke til, hvordan fortælleren får mig til at se.'),('Når jagten går i stå','Mens Ahab vil fremad, får jeg tid til at undersøge en line, en finne eller en mønt. Hvad opdager jeg om folkene undervejs?','Jeg vil læse et teknisk kapitel langsomt nok til at se arbejdet for mig.')]
 else:
  g['length']='135 chapters, an epilogue and introductory material';g['openingChapterLabel']='Chapter 1 — Loomings';g['openingText']=cs[1][0]['paragraphs'][0].split(" It's my way")[0]
  g['about']="When a damp November settles in Ishmael’s soul, he goes to sea. This time he means to go whaling. At an inn in New Bedford he reluctantly shares a bed with Queequeg, a harpooner. The two become friends and ship together on the Pequod out of Nantucket. Only at sea does Captain Ahab tell his crew what he wants from the voyage. The white whale took his leg. He means to hunt it down.\n\nHerman Melville had sailed on a whaler himself. He dedicated the novel to Nathaniel Hawthorne when it appeared in 1851. In the American edition, a school usher and a sub-sub-librarian get their say before Ishmael introduces himself. One looks up the word for whale. The other has gathered everything he can find about the animal, from the Book of Job to a shout from the masthead.\n\nAt sea, the storytelling changes its form just as readily. One night sailors speak across each other as if onstage. Another finds Ishmael at the helm in the light of the fires that render blubber. When he sets out to classify every whale in the world by size, he borrows his system from a bookshelf."
  desc=['A former schoolmaster and merchant sailor, Ishmael ships on the Pequod as an ordinary seaman. He can take on the voice of a preacher, then turn a joke against himself. Notice when his first-person voice steps aside to let somebody else speak.','Captain of the Pequod. Ahab lost a leg to Moby Dick and walks on a replacement carved from a sperm whale’s jaw. When he nails an Ecuadorian doubloon to the mast, every hand on deck can imagine winning it by spotting the whale first.','An enormous sperm whale that sailors know by his white hump and wrinkled brow. Ahab takes the animal’s blow as a personal attack. Ishmael spends an entire chapter exploring how whiteness can inspire both reverence and terror.','The first mate is a Quaker from Nantucket and an accomplished whaleman. He dares speak against Ahab on the quarter-deck. Later, with a loaded musket outside his sleeping captain’s cabin, he must decide what his duty to the crew demands.','The second mate comes from Cape Cod, usually with a pipe between his teeth. He can talk to his oarsmen in pursuit of a whale as easily as he might talk to them at supper. His good humor can keep people going or brush their concerns aside.','Queequeg is a harpooner from Rokovoko, where his father is king. His friendship with Ishmael begins under a shared counterpane in New Bedford. On the crossing to Nantucket he goes overboard to save a man who has been making fun of him.']
  g['whyItMatters']=[dict(title='The price of a doubloon',body='Ahab nails his coin to the mast where everyone can see it. It is a reward for the first sighting of the whale, yet the sailors cannot agree on what the images stamped on it mean. In chapter 99 the coin stays still while one reading after another passes before it.'),dict(title='A book of voices',body='Try reading the sermon in chapter 9 aloud, then listen to the voices on the forecastle at midnight in chapter 40. In both places words set a gathering in motion. In the chapel one man has the floor. On deck it is hard for a sailor to finish even a song.'),dict(title='Work at sea',body='When a whale is killed, the work has barely begun. Blubber must be stripped away, hoisted on deck, minced and boiled. Watch where people put their hands and feet. A loose coil of rope can decide who gets home.')]
  gs=[('Ahab’s obsession','On the quarter-deck Ahab turns his private grievance into a common undertaking. Who agrees with him, and who simply falls silent?','I want to follow the crew’s responses when Ahab asks for its loyalty.'),('What do they see in the whale?','Starbuck sees an animal acting on instinct. Ahab sees a will behind the white head. Ishmael can entertain both ideas long enough to be frightened by them.','I want to follow how the same whale changes from one observer to the next.'),('Looking with Ishmael','Ishmael can begin with a detail on a tool and end in the Book of Job. When do I follow him, and when does he make me doubt?','I want to notice how the storyteller directs my attention.'),('When the chase stops','While Ahab wants to press on, I get time to examine a line, a fin or a coin. What do I learn about the people along the way?','I want to read a technical chapter slowly enough to picture the work.')]
 for c,d in zip(g['cast'],desc):c['description']=d
 g['angleCards']=[dict(title=t,text=a,angleObjective=b) for t,a,b in gs]
 g['acclaim'][0]['quote']='Men det er en stor bog, en meget stor bog, den største bog om havet, der nogensinde er skrevet.' if lang=='da' else 'But it is a great book, a very great book, the greatest book of the sea ever written.'
 if lang=='da':g['acclaim'][0]['context']='Studies in Classic American Literature, 1923 (oversat til dansk her)'
 save(name,g)
